import 'package:cloud_firestore/cloud_firestore.dart';
enum MessageType { text, image, file, voice, system }
enum MessageStatus { sent, delivered, read }
class AttachmentModel { const AttachmentModel({required this.url,required this.name,required this.contentType,required this.sizeBytes}); final String url,name,contentType; final int sizeBytes; factory AttachmentModel.fromMap(Map<String,dynamic> map)=>AttachmentModel(url:map['url'] as String? ?? '',name:map['name'] as String? ?? '',contentType:map['contentType'] as String? ?? '',sizeBytes:(map['sizeBytes'] as num?)?.toInt()??0); Map<String,dynamic> toMap()=>{'url':url,'name':name,'contentType':contentType,'sizeBytes':sizeBytes}; AttachmentModel copyWith({String? url})=>AttachmentModel(url:url??this.url,name:name,contentType:contentType,sizeBytes:sizeBytes); }
class MessageModel { const MessageModel({required this.id,required this.conversationId,required this.senderId,required this.createdAt,required this.type,this.receiverId,this.text='',this.attachment,this.replyToMessageId,this.reactions=const {},this.status=MessageStatus.sent,this.isDeleted=false}); final String id,conversationId,senderId; final String? receiverId,replyToMessageId; final String text; final MessageType type; final AttachmentModel? attachment; final Map<String,List<String>> reactions; final MessageStatus status; final DateTime createdAt; final bool isDeleted;
factory MessageModel.fromMap(String id,Map<String,dynamic> map)=>MessageModel(id:id,conversationId:map['conversationId'] as String? ?? '',senderId:map['senderId'] as String? ?? '',receiverId:map['receiverId'] as String?,text:map['text'] as String? ?? '',type:MessageType.values.byName(map['type'] as String? ?? 'text'),attachment:map['attachment']==null?null:AttachmentModel.fromMap(Map<String,dynamic>.from(map['attachment'])),replyToMessageId:map['replyToMessageId'] as String?,reactions:(map['reactions'] as Map<String,dynamic>? ?? {}).map((key,value)=>MapEntry(key,List<String>.from(value))),status:MessageStatus.values.byName(map['status'] as String? ?? 'sent'),createdAt:(map['createdAt'] as Timestamp?)?.toDate()??DateTime.now(),isDeleted:map['isDeleted'] as bool? ?? false);
Map<String,dynamic> toMap()=>{'conversationId':conversationId,'senderId':senderId,'receiverId':receiverId,'text':text,'type':type.name,'attachment':attachment?.toMap(),'replyToMessageId':replyToMessageId,'reactions':reactions,'status':status.name,'createdAt':Timestamp.fromDate(createdAt),'isDeleted':isDeleted,'updatedAt':FieldValue.serverTimestamp()}; MessageModel copyWith({Map<String,List<String>>? reactions,MessageStatus? status,bool? isDeleted})=>MessageModel(id:id,conversationId:conversationId,senderId:senderId,receiverId:receiverId,text:text,type:type,attachment:attachment,replyToMessageId:replyToMessageId,reactions:reactions??this.reactions,status:status??this.status,createdAt:createdAt,isDeleted:isDeleted??this.isDeleted); }
